  const template = readFileSync(
    new URL("../prompts/batch-translation.prompt.md", import.meta.url),
    "utf8",
  );
  return template
    .replaceAll("{{targetLanguage}}", targetLanguage)
    .replace("{{payload}}", JSON.stringify(payload, null, 2))
    .trimEnd();
}

